/**
 * Normalizes the backend order-list response into a flat frontend shape.
 *
 * The response is the one loaded by src/pages/other/RecentOrder.js
 * (GET /api/v1/auth/orders, handled by OrderApi#list on the backend) and is
 * a ReadableOrderList, i.e. a ReadableList with:
 *   orders       - the orders on this page
 *   pageCount    - total number of pages
 *   totalRecords - total number of records
 *   itemsOnPage  - number of records on this page
 */

function toNumber(value) {
  const n = Number(value);
  return Number.isFinite(n) ? n : 0;
}

export function normalizeOrderList(response) {
  const data = response && typeof response === \"object\" ? response : {};

  const orders = Array.isArray(data.orders) ? data.orders : [];

  return {
    orders,
    pages: toNumber(data.pageCount),
    total: toNumber(data.totalRecords),
    onThisPage: toNumber(data.itemsOnPage),
  };
}
EOF
